/**
 * identity.primary @sequenceStart / @sequenceName: the sequence an @generation "increment"
 * key draws from. Postgres creates it with GENERATED BY DEFAULT AS IDENTITY
 * (SEQUENCE NAME … START WITH …); a live sequence whose declared start or name differs is
 * altered in place (ALTER SEQUENCE … START WITH / RENAME TO), never dropped. Only what the
 * model DECLARES is compared, so a database whose sequence kept an old name after a table
 * rename sees no new change until the model names it. SQLite has no sequences to name.
 */
import { describe, test, expect } from "bun:test";
import { MetaDataLoader, InMemoryStringSource } from "@metaobjectsdev/metadata";
import { buildExpectedSchema } from "../../src/expected-schema.js";
import { diff } from "../../src/diff/index.js";
import { emit } from "../../src/emit/index.js";
import type { SchemaSnapshot as DatabaseSchema } from "../../src/types.js";
import { expectedFromShadow } from "../../src/shadow-expected.js";
import { serializeSnapshot } from "../../src/snapshot/serialize.js";
import { DuplicateSqlNameError } from "../../src/errors.js";

async function schema(pk: Record<string, unknown>) {
  const doc = { "metadata.root": { package: "acme", children: [
    { "object.entity": { name: "Ticket", children: [
      { "source.rdb": { "@table": "Ticket" } },
      { "field.int": { name: "id", "@column": "Id" } },
      { "identity.primary": { name: "pk", "@fields": "id", "@generation": "increment", ...pk } },
    ] } },
  ] } };
  const { root, errors } = await new MetaDataLoader().load([new InMemoryStringSource(JSON.stringify(doc))]);
  expect(errors).toHaveLength(0);
  return buildExpectedSchema(root);
}

const EMPTY = { tables: [], views: [] } as unknown as DatabaseSchema;
const idColumn = (s: DatabaseSchema) => s.tables.find((t) => t.name === "Ticket")!.columns.find((c) => c.name === "Id")!;

/** The live side: the same table, its sequence as Postgres reports it (introspection only). */
function live(expected: DatabaseSchema, sequence: { name: string; start: number }): DatabaseSchema {
  const copy = structuredClone(expected);
  delete idColumn(copy).sequence;
  idColumn(copy).liveSequence = sequence;
  return copy;
}

describe("identity.primary sequence start and name", () => {
  test("the expected column carries only what the model declares", async () => {
    expect(idColumn(await schema({ "@sequenceStart": 1000000000, "@sequenceName": "Old_Id_seq" })).sequence)
      .toEqual({ start: 1000000000, name: "Old_Id_seq" });
    expect(idColumn(await schema({})).sequence).toBeUndefined();
  });

  test("Postgres CREATE names the sequence and its start", async () => {
    const s = await schema({ "@sequenceStart": 1000000000, "@sequenceName": "Old_Id_seq" });
    const { changes } = await diff(s, EMPTY, { dialect: "postgres" });
    expect(emit(changes, { dialect: "postgres" }).up)
      .toContain('"Id" INTEGER GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "Old_Id_seq" START WITH 1000000000)');
  });

  test("a live sequence with another start and name is altered in place, and the down reverses it", async () => {
    const s = await schema({ "@sequenceStart": 1000000000, "@sequenceName": "Old_Id_seq" });
    const { changes } = await diff(s, live(s, { name: "Ticket_Id_seq", start: 1 }), { dialect: "postgres" });
    expect(changes.filter((c) => c.kind === "alter-sequence")).toHaveLength(1);
    const { up, down } = emit(changes, { dialect: "postgres" });
    expect(up).toContain('ALTER SEQUENCE "Ticket_Id_seq" START WITH 1000000000;');
    // START WITH alone only records a restart point: the counter is moved up to it, never down.
    expect(up).toContain(`SELECT setval('"Ticket_Id_seq"', 1000000000, false) FROM "Ticket_Id_seq" WHERE last_value < 1000000000;`);
    expect(up).toContain('ALTER SEQUENCE "Ticket_Id_seq" RENAME TO "Old_Id_seq";');
    expect(down).toContain('ALTER SEQUENCE "Old_Id_seq" RENAME TO "Ticket_Id_seq";');
    expect(down).toContain('ALTER SEQUENCE "Ticket_Id_seq" START WITH 1;');
    expect(up).not.toMatch(/DROP|IDENTITY/);
  });

  test("a live sequence matching the declaration is no change", async () => {
    const s = await schema({ "@sequenceStart": 1000000000, "@sequenceName": "Old_Id_seq" });
    const { changes } = await diff(s, live(s, { name: "Old_Id_seq", start: 1000000000 }), { dialect: "postgres" });
    expect(changes.filter((c) => c.kind === "alter-sequence")).toEqual([]);
  });

  test("undeclared start and name are not compared, whatever the live sequence says", async () => {
    const s = await schema({});
    const { changes } = await diff(s, live(s, { name: "Renamed_Id_seq", start: 500 }), { dialect: "postgres" });
    expect(changes.filter((c) => c.kind === "alter-sequence")).toEqual([]);
  });

  test("SQLite has no sequence to name: no clause, no change, and an advisory when the key is created", async () => {
    const s = await schema({ "@sequenceStart": 1000000000, "@sequenceName": "Old_Id_seq" });
    const { changes, advisories } = await diff(s, EMPTY, { dialect: "sqlite" });
    const { up } = emit(changes, { dialect: "sqlite" });
    expect(up).not.toContain("SEQUENCE");
    expect(up).not.toContain("1000000000");
    expect(advisories).toEqual([{ kind: "sequence-not-applied", table: "Ticket", column: "Id" }]);
    // Once the table exists there is nothing to create, so nothing to say on every later run.
    expect((await diff(s, s, { dialect: "sqlite" })).advisories).toEqual([]);
    // Postgres applies both, so it says nothing.
    expect((await diff(s, EMPTY, { dialect: "postgres" })).advisories).toEqual([]);
  });

  test("shadow path: a model that declares nothing gets no sequence clause and no change", async () => {
    const model = await schema({});
    // The shadow database's own read of the model's tables: introspection fills liveSequence.
    const shadow = live(model, { name: "Ticket_Id_seq", start: 1 });
    const expected = expectedFromShadow(shadow, model);
    expect(idColumn(expected).sequence).toBeUndefined();
    // A live sequence left behind by a table rename, with a non-default start: not compared.
    const { changes } = await diff(expected, live(model, { name: "OldTicket_Id_seq", start: 1000 }), { dialect: "postgres" });
    expect(changes.filter((c) => c.kind === "alter-sequence")).toEqual([]);
    // CREATE from the shadow-read expected side: plain IDENTITY, as before.
    const created = await diff(expected, EMPTY, { dialect: "postgres" });
    expect(emit(created.changes, { dialect: "postgres" }).up).not.toContain("SEQUENCE NAME");
  });

  test("shadow path: what the model declares survives the shadow read", async () => {
    const model = await schema({ "@sequenceStart": 1000000000, "@sequenceName": "Old_Id_seq" });
    const expected = expectedFromShadow(live(model, { name: "Old_Id_seq", start: 1000000000 }), model);
    expect(idColumn(expected).sequence).toEqual({ start: 1000000000, name: "Old_Id_seq" });
  });

  test("offline (committed snapshot): a changed declared start is a change, addressed by the default name", async () => {
    const before = await schema({ "@sequenceStart": 1000 });
    const after = await schema({ "@sequenceStart": 2000 });
    const { changes } = await diff(after, before, { dialect: "postgres" });
    const alter = changes.filter((c) => c.kind === "alter-sequence");
    expect(alter).toHaveLength(1);
    expect(emit(changes, { dialect: "postgres" }).up).toContain('ALTER SEQUENCE "Ticket_Id_seq" START WITH 2000;');
  });

  test("adding the identity to an existing column carries the declared options", () => {
    const { up } = emit([{
      kind: "change-column-identity", table: "Ticket", column: "Id", to: "increment",
      sequence: { name: "Old_Id_seq", start: 1000000000 }, status: "allowed",
    } as never], { dialect: "postgres" });
    expect(up).toContain('ALTER TABLE "Ticket" ALTER COLUMN "Id" ADD GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "Old_Id_seq" START WITH 1000000000);');
  });

  test("a dropped table's down rebuilds it as before: the live sequence is never emitted", async () => {
    const s = await schema({});
    const { changes } = await diff(EMPTY, live(s, { name: "OldTicket_Id_seq", start: 1000 }), { dialect: "postgres", allow: { dropTable: true } } as never);
    expect(emit(changes, { dialect: "postgres" }).down).not.toContain("SEQUENCE NAME");
  });

  test("a snapshot never records the live sequence", async () => {
    const s = await schema({});
    const text = serializeSnapshot(live(s, { name: "OldTicket_Id_seq", start: 1000 }));
    expect(text).not.toContain("OldTicket_Id_seq");
    expect(text).not.toContain("liveSequence");
  });

  test("two tables declaring one sequence name are refused before any SQL is emitted", async () => {
    const doc = { "metadata.root": { package: "acme", children: ["A", "B"].map((n) => (
      { "object.entity": { name: n, children: [
        { "source.rdb": { "@table": n } },
        { "field.int": { name: "id" } },
        { "identity.primary": { name: "pk", "@fields": "id", "@generation": "increment", "@sequenceName": "shared_seq" } },
      ] } })) } };
    const { root, errors } = await new MetaDataLoader().load([new InMemoryStringSource(JSON.stringify(doc))]);
    expect(errors).toHaveLength(0);
    expect(() => buildExpectedSchema(root)).toThrow(DuplicateSqlNameError);
    expect(() => buildExpectedSchema(root)).toThrow(/shared_seq/);
  });
});
